import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { FallLocationWarningFilters, FallWarningCurrentStatus } from '../../../models/FallLocationWarning';
import { useFormOptions } from '../../../hooks/useFormOptions';
import { currentYearDateRange, useReportPeriodFilter } from '../../../hooks/useReportPeriodFilter';
import styles from './FallWarningFiltersBar.module.css';
import {
  LinErpListFilterBar,
  LinReportPeriodSelectorFields,
  SearchTextInput,
  Select,
  SelectOption,
} from '@linm-soft-org/linm-web-common-components';

const TEST_ID_PREFIX = 'fall-warning-list';

interface Props {
  filters: FallLocationWarningFilters;
  onChange: (f: FallLocationWarningFilters) => void;
  onClear: () => void;
  loading?: boolean;
}

const BASE_STATUS_OPTIONS: SelectOption[] = [
  { value: FallWarningCurrentStatus.NotFixed, label: 'Chưa khắc phục' },
  { value: FallWarningCurrentStatus.InProgress, label: 'Đang khắc phục' },
  { value: FallWarningCurrentStatus.Fixed, label: 'Đã khắc phục' },
];

export const FallWarningFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
  loading = false,
}) => {
  const [draft, setDraft] = useState<FallLocationWarningFilters>(filters);
  const { departmentOptions } = useFormOptions('fall-warning-list');

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  const allStatusOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả trạng thái' }, ...BASE_STATUS_OPTIONS],
    [],
  );

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa' }, ...departmentOptions],
    [departmentOptions],
  );

  const commitDates = useCallback(
    (fromDate: string, toDate: string) => {
      setDraft((prev) => {
        const next = { ...prev, fromDate, toDate };
        onChange({ ...next });
        return next;
      });
    },
    [onChange],
  );

  const period = useReportPeriodFilter(commitDates, 'year');

  const hasActiveFilters = !!(
    draft.search ||
    draft.currentStatus ||
    draft.departmentId ||
    period.viewMode !== 'year'
  );

  const handleSearch = () => {
    onChange({
      ...draft,
      fromDate: period.fromDate || draft.fromDate,
      toDate: period.toDate || draft.toDate,
      search: draft.search?.trim() || undefined,
      currentStatus: draft.currentStatus || undefined,
      departmentId: draft.departmentId || undefined,
    });
  };

  const handleClear = () => {
    period.resetToDefaultYear();
    const year = currentYearDateRange();
    setDraft({ fromDate: year.dateFrom, toDate: year.dateTo });
    onClear();
  };

  return (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID_PREFIX}
      fromDate={period.fromDate}
      toDate={period.toDate}
      onDateChange={period.handleDateRangeChange}
      onSearch={handleSearch}
      loading={loading}
      leading={(
        <>
          <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
            <SearchTextInput
              placeholder="Tìm theo vị trí, mã..."
              value={draft.search ?? ''}
              onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
              onSearch={handleSearch}
              testId={`${TEST_ID_PREFIX}-search-text`}
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-status`}>
            <Select
              options={allStatusOptions}
              value={draft.currentStatus ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  currentStatus: e.target.value as FallWarningCurrentStatus | '',
                }))
              }
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-department`}>
            <Select
              options={allDeptOptions}
              value={draft.departmentId ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({ ...prev, departmentId: e.target.value }))
              }
              size="small"
            />
          </div>
          {hasActiveFilters && (
            <button
              className={styles.clearFiltersButton}
              onClick={handleClear}
              type="button"
              title="Xóa bộ lọc"
            >
              <i className="fas fa-times-circle" />
              <span>Xóa bộ lọc</span>
            </button>
          )}
        </>
      )}
      dateLeading={(
        <LinReportPeriodSelectorFields
          testIdPrefix={TEST_ID_PREFIX}
          labels={period.periodLabels}
          viewMode={period.viewMode}
          month={period.month}
          year={period.year}
          quarter={period.quarter}
          yearOptions={period.yearOptions}
          onViewModeChange={period.handleViewModeChange}
          onMonthChange={period.setMonth}
          onYearChange={period.setYear}
          onQuarterChange={period.setQuarter}
        />
      )}
    />
  );
};
